 "content": "def transform(grid):
    """Infer the periodic color sequence of horizontal rows from solid clues."""
    h, w = len(grid), len(grid[0])
    clues = []
    for r, row in enumerate(grid):
        colors = {x for x in row if x != 0}
        if len(colors) > 1:
            return [row[:] for row in grid]
        if colors:
            clues.append((r, next(iter(colors))))
    for period in range(1, h + 1):
        cycle = {}
        for r, color in clues:
            k = r % period
            if k in cycle and cycle[k] != color:
                break
            cycle[k] = color
        else:
            if len(cycle) == period:
                return [[cycle[r % period]] * w for r in range(h)]
    return [row[:] for row in grid]


